 void refreshPrayerStatus(){if(prayerStatus==null||closed)return;final String zone=a.prefs.getString("jakim_zone","");if(zone.isEmpty()){prayerStatus.setText("Zon belum dipilih.\nPilih zon sebenar lokasi anda.\nSumber: e-Solat JAKIM · MYT");return;}prayerStatus.setText("JAKIM · "+zone+"\nMemuat status data tempatan…");a.worker.execute(()->{String info;try{Map<String,JakimCalendar.Day> days=JakimCalendar.load(a,zone);String today=JakimCalendar.key(System.currentTimeMillis());TreeSet<String> dates=new TreeSet<>(days.keySet());File cache=new File(a.getFilesDir(),"jakim-"+zone+".json");SimpleDateFormat date=new SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("ms","MY"));date.setTimeZone(JakimCalendar.MY);info="JAKIM · "+zone+"\n"+(days.containsKey(today)?"Jadual hari ini tersedia":"Tiada jadual tarikh hari ini")+"\n"+days.size()+" hari dalam data tempatan"+(dates.isEmpty()?"":"\n"+dates.first()+" hingga "+dates.last())+"\n"+(cache.isFile()?"Cache disimpan: "+date.format(new Date(cache.lastModified()))+" MYT":"Data offline bawaan; belum ada cache muat turun")+"\nSumber: e-Solat JAKIM · MYT";}catch(Exception unavailable){info="Status jadual tidak tersedia.\nCache sedia ada tidak dipadam.";}final String status=info;a.main.post(()->{if(!closed&&a.settingsScreen==this&&zone.equals(a.prefs.getString("jakim_zone","")))prayerStatus.setText(status);});});}
